				heading: "3. Теорема Пифагора",
				content: `В **прямоугольном треугольнике** стороны, образующие прямой угол, называются **катетами** ($a$ и $b$), а самая длинная сторона напротив прямого угла — **гипотенузой** ($c$).

**Теорема Пифагора**:
$$a^2 + b^2 = c^2$$
*Квадрат гипотенузы равен сумме квадратов катетов.*
* Чтобы найти гипотенузу: $c = \\sqrt{a^2 + b^2}$
* Чтобы найти катет: $a = \\sqrt{c^2 - b^2}$
* **Египетский треугольник**: катеты 3 и 4, гипотенуза 5 ($3^2 + 4^2 = 9 + 16 = 25 = 5^2$).`
