			{
				heading: "1. Генеральная совокупность и выборка",
				content: `**Генеральная совокупность** — это все объекты, о которых мы хотим сделать выводы.

**Выборка** — часть генеральной совокупности, которую реально исследуют. Она должна быть **репрезентативной** (представительной), т.е. отражать свойства всей совокупности.

**Объём выборки** $n$ — количество элементов в выборке.

**Пример:** Чтобы узнать средний рост всех школьников России (генеральная совокупность — миллионы человек), достаточно измерить рост репрезентативной выборки из нескольких тысяч школьников.

**Случайная выборка** — каждый элемент совокупности имеет равные шансы попасть в выборку. Это важно для объективности результатов.`
			},
			{
				heading: "2. Таблицы частот",
				content: `**Частота** $f_i$ — количество раз, которое определённое значение встретилось в выборке.

**Относительная частота** $w_i$ — доля данного значения:
$$w_i = \\frac{f_i}{n}$$

где $n$ — объём выборки. Сумма всех относительных частот равна 1.

**Пример таблицы частот** оценок в классе (25 учеников):

| Оценка | Частота $f_i$ | Отн. частота $w_i$ |
|--------|--------------|-------------------|
| 2 | 2 | 2/25 = 0,08 |
| 3 | 7 | 7/25 = 0,28 |
| 4 | 10 | 10/25 = 0,40 |
| 5 | 6 | 6/25 = 0,24 |
| **Итого** | **25** | **1,00** |`
			},
			{
				heading: "3. Гистограммы и столбчатые диаграммы",
				content: `**Столбчатая диаграмма** используется для дискретных (отдельных) данных. По горизонтальной оси — значения, по вертикальной — частоты (или относительные частоты). Высота каждого столбца равна частоте соответствующего значения.

**Гистограмма** — разновидность столбчатой диаграммы для **непрерывных** данных, сгруппированных в **интервалы** (классы). Площадь каждого прямоугольника пропорциональна частоте соответствующего интервала.

**Полигон частот** — ломаная линия, соединяющая верхние середины столбцов гистограммы. Даёт представление об «форме» распределения.

**Принципы хорошей диаграммы:**
* Ось подписана с единицами измерения.
* Масштаб равномерный.
* Есть заголовок.
* Нет 3D-эффектов, искажающих восприятие.`
			},
			{
				heading: "4. Круговые диаграммы",
				content: `**Круговая диаграмма** наглядно показывает соотношение частей и целого. Целый круг (360°) делится на секторы пропорционально относительным частотам.

**Угол сектора** для категории с относительной частотой $w_i$:
$$\\alpha_i = w_i \\times 360°$$

**Пример:** Оценки в классе (из таблицы выше):
* Оценка 2: $0{,}08 \\times 360° = 28{,}8°$
* Оценка 3: $0{,}28 \\times 360° = 100{,}8°$
* Оценка 4: $0{,}40 \\times 360° = 144°$
* Оценка 5: $0{,}24 \\times 360° = 86{,}4°$

Сумма углов = $360°$ ✓

**Когда использовать:** круговая диаграмма хорошо работает, когда категорий немного (2–6) и нужно показать структуру целого.`
			}
