			{
				heading: "1. Виды событий",
				content: `**Несовместные события** — два события, которые не могут произойти одновременно в одном опыте.

**Пример:** При броске кубика «выпало 3» и «выпало 5» — несовместные, они не могут случиться одновременно.

**Совместные события** — могут произойти одновременно.

**Пример:** «Выпало чётное число» и «выпало число больше 4» — совместные, т.к. 6 — чётное и больше 4.

**Противоположные события** $A$ и $\\bar{A}$ — несовместные события, одно из которых обязательно произойдёт. $P(A) + P(\\bar{A}) = 1$.

**Независимые события** — исход одного не влияет на вероятность другого. **Пример:** два броска монеты.

**Зависимые события** — исход одного влияет на вероятность другого. **Пример:** последовательное извлечение шаров без возвращения.`
			},
			{
				heading: "2. Формула сложения вероятностей",
				content: `**Для несовместных событий** $A$ и $B$ (не могут случиться одновременно):

$$P(A \\cup B) = P(A) + P(B)$$

**Пример:** Бросают кубик. Вероятность выпадения 2 или 5:
$$P(2 \\text{ или } 5) = P(2) + P(5) = \\frac{1}{6} + \\frac{1}{6} = \\frac{2}{6} = \\frac{1}{3}$$

**Для совместных событий** (могут произойти одновременно):

$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$

Вычитаем $P(A \\cap B)$, так как при простом сложении мы дважды учли пересечение.

**Пример:** Бросают кубик. A = «чётное» (2,4,6), B = «больше 4» (5,6).
$P(A) = 3/6$, $P(B) = 2/6$, $P(A \\cap B) = P(6) = 1/6$.
$$P(A \\cup B) = \\frac{3}{6} + \\frac{2}{6} - \\frac{1}{6} = \\frac{4}{6} = \\frac{2}{3}$$`
			},
			{
				heading: "3. Умножение вероятностей независимых событий",
				content: `Если события $A$ и $B$ **независимы**, то вероятность того, что оба произойдут:

$$P(A \\cap B) = P(A) \\cdot P(B)$$

**Пример 1:** Монету бросают дважды. Вероятность выпадения двух орлов:
$$P(ОО) = P(О) \\cdot P(О) = \\frac{1}{2} \\cdot \\frac{1}{2} = \\frac{1}{4}$$

**Пример 2:** Стрелок попадает в цель с вероятностью 0,8. Два независимых выстрела. Вероятность двух попаданий:
$$P = 0{,}8 \\cdot 0{,}8 = 0{,}64$$

**Пример 3:** Вероятность хотя бы одного попадания из двух выстрелов (p = 0,8 каждый):
$$P(\\text{хотя бы одно}) = 1 - P(\\text{оба промаха}) = 1 - 0{,}2 \\cdot 0{,}2 = 1 - 0{,}04 = 0{,}96$$`
			},
			{
				heading: "4. Классификация и связи между формулами",
				content: `**Итоговая схема:**

| Тип событий | Формула суммы | Формула произведения |
|-------------|---------------|----------------------|
| Несовместные | $P(A+B) = P(A)+P(B)$ | Не применяется |
| Совместные | $P(A+B) = P(A)+P(B)-P(AB)$ | — |
| Независимые | — | $P(AB) = P(A) \\cdot P(B)$ |

**Частные случаи:**
* Сумма вероятностей всех элементарных несовместных исходов = 1.
* $P(A) + P(\\bar{A}) = 1$ — обязательно для противоположных событий.
* Для $k$ независимых событий с одинаковой вероятностью $p$: $P(\\text{все}) = p^k$.`
			}
