			{
				heading: "1. Уравнение окружности",
				content: `Окружность — это геометрическое место точек плоскости, равноудалённых от данной точки (центра) на расстояние $r$ (радиус).

Если центр окружности находится в точке $C(a, b)$, то для любой точки $M(x, y)$ на окружности:
$$|CM| = r$$
По формуле расстояния между двумя точками:
$$\\sqrt{(x-a)^2 + (y-b)^2} = r$$
Возводя в квадрат, получаем **стандартное уравнение окружности**:
$$(x - a)^2 + (y - b)^2 = r^2$$

**Частные случаи:**
- Окружность с центром в начале координат: $x^2 + y^2 = r^2$
- Единичная окружность: $x^2 + y^2 = 1$

**Пример:** Запишите уравнение окружности с центром $C(3, -1)$ и радиусом $r = 5$.
$$(x - 3)^2 + (y + 1)^2 = 25$$`
			},
			{
				heading: "2. Общее уравнение окружности",
				content: `Раскрыв скобки в стандартном уравнении, получим **общее уравнение окружности**:
$$x^2 + y^2 + Dx + Ey + F = 0$$
где $D = -2a$, $E = -2b$, $F = a^2 + b^2 - r^2$.

Чтобы перейти от общего уравнения к стандартному, нужно **выделить полный квадрат**:
$$x^2 + Dx = \\left(x + \\frac{D}{2}\\right)^2 - \\frac{D^2}{4}$$

**Пример:** Найдите центр и радиус: $x^2 + y^2 - 6x + 4y - 3 = 0$

Выделяем полные квадраты:
$$(x^2 - 6x + 9) + (y^2 + 4y + 4) = 3 + 9 + 4$$
$$(x - 3)^2 + (y + 2)^2 = 16$$

Центр $C(3, -2)$, радиус $r = 4$.

**Условие:** уравнение $x^2 + y^2 + Dx + Ey + F = 0$ задаёт окружность тогда и только тогда, когда $\\frac{D^2}{4} + \\frac{E^2}{4} - F > 0$, т.е. $r^2 > 0$.`
			},
			{
				heading: "3. Взаимное расположение прямой и окружности",
				content: `Пусть дана окружность с центром $C(a,b)$, радиусом $r$, и прямая $l: Ax + By + C = 0$.

Расстояние от центра до прямой:
$$d = \\frac{|Aa + Bb + C|}{\\sqrt{A^2 + B^2}}$$

**Три случая:**
1. $d > r$ — прямая и окружность **не пересекаются** (нет общих точек)
2. $d = r$ — прямая **касается** окружности (одна общая точка)
3. $d < r$ — прямая **пересекает** окружность в двух точках

**Длина хорды**, которую отсекает прямая:
$$|AB| = 2\\sqrt{r^2 - d^2}$$

**Пример:** Окружность $x^2 + y^2 = 25$, прямая $3x + 4y - 15 = 0$.
$$d = \\frac{|3 \\cdot 0 + 4 \\cdot 0 - 15|}{\\sqrt{9+16}} = \\frac{15}{5} = 3$$
Так как $d = 3 < r = 5$, прямая пересекает окружность. Длина хорды: $2\\sqrt{25-9} = 2\\cdot 4 = 8$.`
			},
			{
				heading: "4. Касательная к окружности",
				content: `**Касательная** к окружности в точке касания перпендикулярна радиусу, проведённому в эту точку.

Уравнение касательной к окружности $(x-a)^2 + (y-b)^2 = r^2$ в точке $(x_0, y_0)$:
$$(x_0 - a)(x - a) + (y_0 - b)(y - b) = r^2$$

**Частный случай** (центр в начале координат $x^2 + y^2 = r^2$):
$$x_0 \\cdot x + y_0 \\cdot y = r^2$$

**Пример:** Найдите уравнение касательной к окружности $x^2 + y^2 = 25$ в точке $(3, 4)$.
$$3x + 4y = 25$$

**Касательные из внешней точки:** Из точки $P(p, q)$, лежащей вне окружности $x^2+y^2=r^2$, можно провести две касательные. Их длина:
$$t = \\sqrt{p^2 + q^2 - r^2}$$`
			}
