				heading: "2. Задачи на кредиты",
				content: `При аннуитетном кредите ежемесячный платёж $A$ рассчитывается по формуле:
$$A = P \\cdot \\frac{i(1+i)^n}{(1+i)^n - 1}$$
где $P$ — сумма кредита, $i$ — ежемесячная процентная ставка ($i = r/(12 \\cdot 100)$), $n$ — количество месяцев.

Общая выплата за весь период: $S = A \\cdot n$

Переплата: $P_{\\text{пер}} = S - P$

**Упрощённый подход для ЕГЭ:** Часто в задачах используются целые ставки и небольшие периоды, что позволяет вести расчёт пошагово.`
