var mixedBank = (rng) => {
	const pools = [
		arithmeticBank(rng),
		algebraBank(rng),
		geometryBank(rng),
		trigonometryBank(rng),
		logarithmsBank(rng),
		probabilityBank(rng),
		calculusApplicationsBank(rng)
	];
	const out = [];
	const used = /* @__PURE__ */ new Set();
	for (let i = 0; i < 15; i += 1) {
		const pool = pools[i % pools.length];
		let index = (i * 3 + 1) % pool.length;
		let candidate = pool[index];
		let guard = 0;
		while (used.has(candidate.question) && guard < pool.length) {
			index = (index + 1) % pool.length;
			candidate = pool[index];
			guard += 1;
		}
		used.add(candidate.question);
		out.push(candidate);
	}
	return out;
};
var buildQuestionBank = (kind, rng) => {
	switch (kind) {
		case "percent": return percentBank(rng);
		case "algebra": return algebraBank(rng);
		case "functions":
		case "linearFunction":
		case "quadraticFunction":
		case "rationalFunction":
		case "exponentialFunction":
		case "functionTransform": return functionsBank(rng);
		case "derivative": return derivativeBank(rng);
		case "integral": return integralBank(rng);
		case "calculusApplications": return calculusApplicationsBank(rng);
		case "geometry": return geometryBank(rng);
		case "stereometry": return stereometryBank(rng);
		case "trigonometry": return trigonometryBank(rng);
		case "logarithms": return logarithmsBank(rng);
		case "probability": return probabilityBank(rng);
		case "complex": return complexBank(rng);
		case "analytic": return analyticBank(rng);
		case "limits": return limitsBank(rng);
		case "diffeq": return diffeqBank(rng);
		case "linalg": return linalgBank(rng);
		case "olympiad":
		case "logic": return olympiadBank(rng);
		case "higher":
		case "series": return higherBank(rng);
		case "ege":
		case "review": return mixedBank(rng);
		default: return arithmeticBank(rng);
	}
};
